    margin-bottom: var(--spacing-md);
  }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .faq-question {
    min-height: 56px;
  }

  .faq-category h2 {
    font-size: 1.75rem;
    margin-top: var(--spacing-xl);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .faq-question::after,
  .faq-answer {
    transition: none !important;
  }
}
